                for _ in range(turns):
                    x, y = y, -x
                pts.append((x, y))
            minr = min(r for r, c in pts)
            minc = min(c for r, c in pts)
            variants.add(tuple(sorted((r - minr, c - minc) for r, c in pts)))

    out = [row[:] for row in grid]
