from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v != 0)
    marker = min(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]

    # Find every translation of the marker shape, including rotations/reflections,
    # that falls entirely on empty cells.
    shapes = set()
    for flip in (1, -1):
        for turns in range(4):
            pts = []
            for r, c in points:
                x, y = r, flip * c
                for _ in range(turns):
                    x, y = y, -x
                pts.append((x, y))
            minr = min(r for r, c in pts)
            minc = min(c for r, c in pts)
            shapes.add(tuple(sorted((r - minr, c - minc) for r, c in pts)))

    out = [row[:] for row in grid]
    for shape in shapes:
        sh = max(r for r, c in shape) + 1
        sw = max(c for r, c in shape) + 1
        for r0 in range(h - sh + 1):
            for c0 in range(w - sw + 1):
                cells = [(r0 + r, c0 + c) for r, c in shape]
                if all(grid[r][c] == 0 for r, c in cells):
                    for r, c in cells:
                        out[r][c] = marker
    return out
